syntax:
class Base {
    virtual void virtFunc();  // Compiler adds a vptr to Base objects and creates a vtable with pointers to virtual functions.
};

class Derived : public Base {  // For Derived, compiler may add another vptr if it has its own virtual functions.
    void virtFunc() override;  // Overrides Base::virtFunc(); vtable for Derived points to this implementation.
    // In multiple inheritance, e.g., class MultiDerived : public Base1, public Base2,
    // the compiler adjusts the 'this' pointer when calling functions from Base2 to account for the offset.
};

code_example:
#include <iostream>

class Base {
public:
    virtual void virtFunc() { std::cout << "Base's virtual function" << std::endl; }  // Virtual function declaration
};

class Derived : public Base {
public:
    void virtFunc() override { std::cout << "Derived's virtual function" << std::endl; }  // Overrides Base::virtFunc()
};

int main() {
    Derived d;  // Object 'd' includes a vptr pointing to Derived's vtable
    Base* ptr = &d;  // Pointer to Base, but points to Derived object
    ptr->virtFunc();  // Virtual dispatch: uses d's vptr, indexes vtable, calls Derived::virtFunc() with adjusted 'this' if needed
    return 0;
}
